---00000000000000000003和00000000000000000004账套

--BOK_SCENESUBJECT
delete from BOK_SCENESUBJECT where BOOKSET_ID = '00000000000000000003' OR BOOKSET_ID = '00000000000000000004';

select B.BOOKSET_ID, A.SCENE_NODE_ID, A.SUBJECT_NO, A.CD_FLAG, A.FORM_ELE,A.BOK_DETAIL_ID, A.CREATE_USER, A.CREATE_DEPT, A.CREATE_TIME, A.UPDATE_USER, A.UPDATE_TIME, A.ACCOUNT_NET 
from BOK_SCENESUBJECT A, BOK_BOOKSET B where A.BOOKSET_ID = '00000000000000000002' AND B.BOOKSET_ID != A.BOOKSET_ID and B.BOOKSET_TYPE = '01'
AND B.BOOKSET_ID != 'BANK0001';

--BOK_TABLEDICT
delete from BOK_TABLEDICT where BOOKSET_ID = '00000000000000000003' OR BOOKSET_ID = '00000000000000000004';

select B.BOOKSET_ID, A.DICT_ID, A.DICT_CODE, A.TABLE_ID, A.DICT_NAME, A.DICT_TYPE, A.DICT_SOURCE, A.CREATE_USER, A.CREATE_DEPT, A.CREATE_TIME, A.UPDATE_USER, A.UPDATE_TIME 
from BOK_TABLEDICT A, BOK_BOOKSET B where A.BOOKSET_ID = '00000000000000000002' AND B.BOOKSET_ID != A.BOOKSET_ID and B.BOOKSET_TYPE = '01'
AND B.BOOKSET_ID != 'BANK0001';































